import { z } from "zod";
import { buildBitfabRequestHeaders } from "../clientHeaders.js";
import { getConfig } from "../config.js";
import { emitPageLink } from "../pageLink.js";
import { positionalArgs } from "../parseArgs.js";
const ticketResponseSchema = z.object({ id: z.uuid() });
export async function runStartTemplatePreview(platform, pluginVersion) {
    const args = positionalArgs([{ name: "functionKey", description: "Trace function key." }], process.argv, { description: "Print a link to the page and exit." });
    const config = getConfig();
    if (!config.apiKey) {
        throw new Error("Log in to Bitfab before opening a template preview.");
    }
    const response = await fetch(`${config.serviceUrl.replace(/\/$/, "")}/api/plugin/handoff-tickets`, {
        method: "POST",
        headers: buildBitfabRequestHeaders(config.apiKey, pluginVersion, platform),
        body: JSON.stringify({
            kind: "template.preview",
            ttlSeconds: 1800,
        }),
        signal: AbortSignal.timeout(30_000),
    });
    if (!response.ok) {
        throw new Error(`Could not open template preview (HTTP ${response.status}).`);
    }
    const parsedTicket = ticketResponseSchema.safeParse(await response.json());
    if (!parsedTicket.success) {
        throw new Error("Could not open template preview: invalid ticket response.");
    }
    const ticket = parsedTicket.data;
    emitPageLink(buildTemplatePreviewPath(args[0], ticket.id));
}
export function buildTemplatePreviewPath(functionKey, ticketId) {
    const path = `/plugin/trace-functions/${encodeURIComponent(functionKey)}/template-preview`;
    return ticketId ? `${path}?ticket=${encodeURIComponent(ticketId)}` : path;
}
